WITH deduped AS (SELECT * FROM suppliers QUALIFY ROW_NUMBER() OVER (PARTITION BY city, country ORDER BY rating DESC NULLS LAST, id ASC) = 1) SELECT city, SUM(rating) AS total_rating, SUM(CASE WHEN city = 'Bangkok' THEN rating ELSE 0 END) AS bangkok_rating, SIZE(COLLECT_SET(city)) AS num_cities, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, PERCENTILE_APPROX(rating, 0.5) AS rating_p50 FROM deduped GROUP BY city HAVING bangkok_rating > 0;
